import json
import sys

status, statusCode, message, resultJson, ready = "ok", 200, "No deployment dependencies found", "{}", False
try:
    body = json.loads(sys.argv[1])
    rows = body.get("Results") if isinstance(body, dict) else None
    count = body.get("Count") if isinstance(body, dict) else None
    if not isinstance(rows, list) or isinstance(count, bool) or not isinstance(count, int) or count < 0:
        raise ValueError("Deployment response must contain a non-negative integer Count and Results array.")
    if count == 0 and rows:
        raise ValueError("Deployment response is internally inconsistent: Count is zero but Results is not empty.")
    if count > 0:
        if not rows or not isinstance(rows[0].get("WorkloadDefinition"), dict) or rows[0]["WorkloadDefinition"].get("Moid") != sys.argv[2]:
            status, statusCode, message = "identity-mismatch", 409, "Deployment dependency evidence does not preserve the requested relationship."
        else:
            status, statusCode, message = "dependency-conflict", 409, "Workload definition is referenced by %d deployment(s); deletion is blocked." % count
        resultJson = json.dumps({"error":message,"deploymentCount":count,"mutationSubmitted":False}, separators=(",",":"))
    else:
        resultJson = json.dumps({"deploymentCount":0,"safeToSubmitDelete":True}, separators=(",",":"))
    ready = True
except Exception as exc:
    status, statusCode, message = "malformed", 502, str(exc)
    resultJson, ready = json.dumps({"error":message}, separators=(",",":")), True
